<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Mfa\Domain\PublicLoginMfaBuildResponse;
use Civi\Lughauth\Features\OAuth\Mfa\Application\Usecase\UserMfa;
use Civi\Lughauth\Features\OAuth\Mfa\Domain\Gateway\UserMfaGateway;

final class MfaDomainUnitTest extends TestCase
{
    // --- PublicLoginMfaBuildResponse ---

    public function test_public_login_mfa_build_response_stores_required_field(): void
    {
        $r = new PublicLoginMfaBuildResponse('seed-abc');
        $this->assertSame('seed-abc', $r->seed);
        $this->assertNull($r->message);
        $this->assertNull($r->image);
        $this->assertNull($r->url);
    }

    public function test_public_login_mfa_build_response_stores_optional_fields(): void
    {
        $r = new PublicLoginMfaBuildResponse('seed', 'Scan this QR code', 'base64==', 'otpauth://totp/...');
        $this->assertSame('seed', $r->seed);
        $this->assertSame('Scan this QR code', $r->message);
        $this->assertSame('base64==', $r->image);
        $this->assertSame('otpauth://totp/...', $r->url);
    }

    // --- UserMfa ---

    public function test_user_mfa_configuration_for_new_mfa_delegates(): void
    {
        $expected = new PublicLoginMfaBuildResponse('seed-xyz', 'msg', 'img', 'url');
        $gateway = new class ($expected) implements UserMfaGateway {
            public function __construct(private PublicLoginMfaBuildResponse $r)
            {
            }
            public function configurationForNewMfa(string $tenant, string $username): PublicLoginMfaBuildResponse
            {
                return $this->r;
            }
            public function verifyOtp(string $tenant, string $username, string $otp): bool
            {
                return false;
            }
            public function verifyNewOpt(string $tenant, string $username, string $seed, string $otp): bool
            {
                return false;
            }
            public function storeSeed(string $tenant, string $username, string $seed): void
            {
            }
        };

        $usecase = new UserMfa($gateway);
        $result = $usecase->configurationForNewMfa('t', 'alice');
        $this->assertSame('seed-xyz', $result->seed);
    }

    public function test_user_mfa_verify_otp_delegates(): void
    {
        $gateway = new class () implements UserMfaGateway {
            public function configurationForNewMfa(string $tenant, string $username): PublicLoginMfaBuildResponse
            {
                return new PublicLoginMfaBuildResponse('s');
            }
            public function verifyOtp(string $tenant, string $username, string $otp): bool
            {
                return $otp === '123456';
            }
            public function verifyNewOpt(string $tenant, string $username, string $seed, string $otp): bool
            {
                return false;
            }
            public function storeSeed(string $tenant, string $username, string $seed): void
            {
            }
        };

        $usecase = new UserMfa($gateway);
        $this->assertTrue($usecase->verifyOtp('t', 'alice', '123456'));
        $this->assertFalse($usecase->verifyOtp('t', 'alice', 'wrong'));
    }

    public function test_user_mfa_verify_new_opt_delegates(): void
    {
        $gateway = new class () implements UserMfaGateway {
            public function configurationForNewMfa(string $tenant, string $username): PublicLoginMfaBuildResponse
            {
                return new PublicLoginMfaBuildResponse('s');
            }
            public function verifyOtp(string $tenant, string $username, string $otp): bool
            {
                return false;
            }
            public function verifyNewOpt(string $tenant, string $username, string $seed, string $otp): bool
            {
                return $seed === 'seed' && $otp === '654321';
            }
            public function storeSeed(string $tenant, string $username, string $seed): void
            {
            }
        };

        $usecase = new UserMfa($gateway);
        $this->assertTrue($usecase->verifyNewOpt('t', 'alice', 'seed', '654321'));
        $this->assertFalse($usecase->verifyNewOpt('t', 'alice', 'seed', 'wrong'));
    }

    public function test_user_mfa_store_seed_delegates(): void
    {
        $stored = null;
        $gateway = new class ($stored) implements UserMfaGateway {
            public ?string $stored = null;
            public function configurationForNewMfa(string $tenant, string $username): PublicLoginMfaBuildResponse
            {
                return new PublicLoginMfaBuildResponse('s');
            }
            public function verifyOtp(string $tenant, string $username, string $otp): bool
            {
                return false;
            }
            public function verifyNewOpt(string $tenant, string $username, string $seed, string $otp): bool
            {
                return false;
            }
            public function storeSeed(string $tenant, string $username, string $seed): void
            {
                $this->stored = $seed;
            }
        };

        $usecase = new UserMfa($gateway);
        $usecase->storeSeed('t', 'alice', 'my-seed-value');
        $this->assertSame('my-seed-value', $gateway->stored);
    }
}
